import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`Отрицательный תזרים: -10,750 ₪, זמן החזר «—», плашка предупреждения #80ff63 #22ce3e ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, { ...SET1, monthlyLoanPayment: '30000' });

      await expectResult(page, 'תזרים חודשי משוער', '-10,750 ₪');
      await expectResult(page, 'זמן החזר ההון העצמי', '—');
      await expect(page.getByText('התזרים לא חיובי').first()).toBeVisible();
      await expect(page.getByText(/^התזרים החודשי שלילי:/)).toBeVisible();
    });
  }
});
